<script>
(function(){const range=document.querySelector('[data-strength-range]');const output=document.querySelector('[data-strength-output]');const label=document.querySelector('[data-strength-label]');if(!range||!output||!label)return;const copy=v=>v<=10?'Natural / believable':v<=30?'Polished tourist':v<=50?'Vacation fantasy':v<=70?'Very extra':v<=90?'Ridiculously touristy':'Maximum vacation nonsense';const render=()=>{const v=parseInt(range.value||'0',10);output.textContent=String(v);label.textContent=copy(v);};range.addEventListener('input',render);render();})();
